1	import * as path from "node:path";
2	import { ToolCall } from "../types.js";
3	import { normalizeToolArguments } from "./tool_arguments.js";
4	import { forbiddenDeletion } from "../tools.js";
5	import { type EffectClass } from "./capabilities.js";
6	import { argsFingerprint } from "./operation_identity.js";
7	import { PolicyContext } from "./approval_policy.js";
8	import { isWorkspaceTrusted } from "../workspace_trust.js";
9	import { ExecutionReceipt, InvocationContext, extractTargetResources } from "./spine.js";
10	import { repairJsonWithClass, isWriteOrExecTool } from "../parser.js";
11	import { oneLine } from "../skills.js";
12	import { VERIFICATION_CONFIG_PROTECTED, splitSubcommands, type VerificationEditContext, type VerificationShellChange } from "../security.js";
13	import { decideManagedCommand, describeSource, permitsEgressHost, type EffectivePolicy } from "./managed_policy.js";
14	import { approvalDecisionSource, clampApprovalSettings, humanRequirementForEffect, type HumanRequirement } from "./policy_runtime.js";
15	import { sandboxNetworkNotice } from "../sandbox.js";
16	import { sandboxDenialEvent, sandboxEngineLabel } from "../sandbox_events.js";
17	import { hasExecutedTests, isVerifierDeliverableBound, isFilteredVerifierCommand } from "../tester.js";
18	import { toolGroupOf } from "./tool_groups.js";
19	import { judgeWithoutCopy, trustedDeliverablesFromBaseline } from "./independent_check.js";
20	import { createHash } from "node:crypto";
21	import { failedCheckFrom, attemptEvidence, recordAttempt, convergenceSignal, convergenceHistory } from "./objective.js";
22	import { recordTestEdit, recordUnverifiableTestEdit } from "./regression_obligations.js";
23	import { FILE_EDIT_TOOLS, describeChange, editTarget, snapshot } from "../file_diff.js";
24	import { roleToolAllowList, roleToolDenyList } from "./roles.js";
25	import { decideCommand, describePrefix, type CommandVerdict, type CommandRuleDecision } from "./command_rules.js";
26	import { redactSecrets } from "../ui.js";
27	import { MAY_OUTLIVE_COMMAND, ConfirmHandler, observationKey, egressOriginOf, READ_ONLY_TOOLS, logAudit } from "./agent_support.js";
28	import { buildNeedsInput, type NeedsInputQuestion } from "./needs_input.js";
29	import {
30	  skillConstraintsEnabled,
31	  skillConfirmWorkspaceEnabled,
32	  resolveSkillToolAllowed,
33	  skillIntegrityMode,
34	} from "./skill_activation.js";
35	import * as fs from "node:fs";
36	
37	export async function dispatchToolCallImpl(this: any, call: ToolCall,
38	    currentStep: number,
39	    actor: "agent" | "subagent" = "agent",
40	    onConfirm?: ConfirmHandler): Promise<{ receipt: ExecutionReceipt; shouldExit: boolean }> {
41	  const toolName = call.function.name;
42	  let args: any = {};
43	  let structurallyRepaired = (call as any).repaired === "structural";
44	
45	  try {
46	    args =
47	      typeof call.function.arguments === "string"
48	        ? JSON.parse(call.function.arguments)
49	        : call.function.arguments;
50	  } catch {
51	    if (typeof call.function.arguments === "string") {
52	      try {
53	        const { value, repaired } = repairJsonWithClass(call.function.arguments);
54	        if (repaired === "structural") structurallyRepaired = true;
55	        args = value && typeof value === "object" ? value : { raw: call.function.arguments };
56	      } catch {
57	        structurallyRepaired = true;
58	        args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
59	      }
60	    } else {
61	      args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
62	    }
63	  }
64	  if (structurallyRepaired && isWriteOrExecTool(toolName)) {
65	    return {
66	      receipt: {
67	        invocationId: call.id,
68	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
69	        actor,
70	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
71	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
72	        toolName,
73	        targetResources: [],
74	        success: false,
75	        output: "",
76	        error: `Tool call "${toolName}" rejected: arguments required structural JSON repair (truncated or unclosed string/bracket). Re-issue the call with complete valid JSON arguments.`,
77	        durationMs: 0,
78	        candidateMutated: false,
79	        status: "DENIED",
80	        timestamp: new Date().toISOString(),
81	        simulated: Boolean(this.config.dryRun),
82	      },
83	      shouldExit: false,
84	    };
85	  }
86	
87	  args = normalizeToolArguments(toolName, args, this.getEffectiveTools());
88	
89	  const skillAttr = () => this.skillActivations?.attribution?.() ?? {};
90	  const recordReceipt = (receipt: ExecutionReceipt) => {
91	    this.lastToolReceipts = [...(this.lastToolReceipts || []), receipt].slice(-32);
92	    return receipt;
93	  };
94	
95	  // Delegated authority is checked at the dispatcher as well as when schemas are built. This is the
96	  // enforcement point for malformed/native/text tool calls and extension tools alike.
97	  if (this.delegatedToolAllowList && !this.delegatedToolAllowList.has(toolName)) {
98	    return {
99	      receipt: recordReceipt({
100	        invocationId: call.id,
101	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
102	        actor,
103	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
104	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
105	        toolName,
106	        targetResources: extractTargetResources(toolName, args),
107	        success: false,
108	        output: "",
109	        error: `Delegation authority denied tool '${toolName}'.`,
110	        durationMs: 0,
111	        candidateMutated: false,
112	        status: "DENIED",
113	        denialReason: "DELEGATION_AUTHORITY",
114	        timestamp: new Date().toISOString(),
115	        simulated: Boolean(this.config.dryRun),
116	        ...skillAttr(),
117	      }),
118	      shouldExit: false,
119	    };
120	  }
121	
122	  // A restricted role is refused any tool outside its allow-list, whatever the model was told or claims. A write or
123	  // exec call in read-only mode is left to the read-only check, which refuses it with its own reason.
124	  const roleAllowed = roleToolAllowList(this.role);
125	  const roleDenied = roleToolDenyList(this.role);
126	  const denyListed = Boolean(roleDenied?.has(toolName));
127	  if (denyListed || (roleAllowed && !roleAllowed.has(toolName) && !(this.isReadOnly() && isWriteOrExecTool(toolName)))) {
128	    return {
129	      receipt: recordReceipt({
130	        invocationId: call.id,
131	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
132	        actor,
133	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
134	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
135	        toolName,
136	        targetResources: [],
137	        success: false,
138	        output: "",
139	        error: denyListed
140	          ? `Tool "${toolName}" is not available to role '${this.role}': tools that reach outside the task (${[...roleDenied!].join(", ")}) are not part of that role. Do the work with the tools you have, or report what you could not do.`
141	          : `Tool "${toolName}" is not permitted for role '${this.role}'. Permitted tools: ${[...roleAllowed!].join(", ")}.`,
142	        durationMs: 0,
143	        candidateMutated: false,
144	        status: "DENIED",
145	        timestamp: new Date().toISOString(),
146	        simulated: Boolean(this.config.dryRun),
147	        ...skillAttr(),
148	      }),
149	      shouldExit: false,
150	    };
151	  }
152	
153	  // WP-GS-03: optional skill constraint intersection (never expands session authority).
154	  if (toolName !== "activate_skill" && skillConstraintsEnabled()) {
155	    const cur = this.skillActivations?.current?.();
156	    if (cur && !resolveSkillToolAllowed(toolName, cur.constraints)) {
157	      return {
158	        receipt: recordReceipt({
159	          invocationId: call.id,
160	          taskId: this.activeWorktree?.taskId || this.currentTaskId,
161	          actor,
162	          executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
163	          capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
164	          toolName,
165	          targetResources: extractTargetResources(toolName, args),
166	          success: false,
167	          output: "",
168	          error: `Skill constraint denied: tool '${toolName}' is not permitted while skill '${cur.skillName}' is active.`,
169	          durationMs: 0,
170	          candidateMutated: false,
171	          status: "DENIED",
172	          denialReason: "SKILL_CONSTRAINT",
173	          timestamp: new Date().toISOString(),
174	          simulated: Boolean(this.config.dryRun),
175	          ...skillAttr(),
176	        }),
177	        shouldExit: false,
178	      };
179	    }
180	  }
181	
182	  // WP-GS-02 live integrity: block tools if activated skill file drifted.
183	  if (toolName !== "activate_skill" && skillIntegrityMode() === "live") {
184	    const cur = this.skillActivations?.current?.();
185	    if (cur) {
186	      const check = this.skillActivations.liveIntegrityBlocked(() => {
187	        try {
188	          const raw = fs.readFileSync(cur.sourcePath, "utf8");
189	          const close = raw.indexOf("\n---", 3);
190	          if (raw.startsWith("---") && close > 0) return raw.slice(close + 4).trim();
191	          return raw.trim();
192	        } catch {
193	          return null;
194	        }
195	      });
196	      if (check.blocked) {
197	        return {
198	          receipt: recordReceipt({
199	            invocationId: call.id,
200	            taskId: this.activeWorktree?.taskId || this.currentTaskId,
201	            actor,
202	            executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
203	            capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
204	            toolName,
205	            targetResources: [],
206	            success: false,
207	            output: "",
208	            error: check.reason || "SKILL_INTEGRITY",
209	            durationMs: 0,
210	            candidateMutated: false,
211	            status: "DENIED",
212	            denialReason: "SKILL_INTEGRITY",
213	            timestamp: new Date().toISOString(),
214	            simulated: Boolean(this.config.dryRun),
215	            ...skillAttr(),
216	          }),
217	          shouldExit: false,
218	        };
219	      }
220	    }
221	  }
222	
223	  try {
224	    const isPublicEgress = ["search_web", "fetch_web", "browser_navigate", "browser_type"].includes(toolName);
225	    if (!isPublicEgress) {
226	      const serialized = JSON.stringify(args);
227	      const restored = this.securityManager.getVault().restore(serialized, { isAuthorizedSink: true });
228	      if (restored !== serialized) {
229	        args = JSON.parse(restored);
230	      }
231	    }
232	  } catch {}
233	
234	  if (this.flightRecorder) {
235	    this.flightRecorder.recordToolCall(currentStep, call.id, toolName, args);
236	  }
237	
238	  // Safety guard against dangerous deletion targets: denied before dispatch or any approval prompt.
239	  const refusedDeletion = toolName === "delete_file" ? forbiddenDeletion(this.config.workspace, String(args.path || "")) : null;
240	  if (refusedDeletion) {
241	    return {
242	      receipt: {
243	        invocationId: call.id,
244	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
245	        actor,
246	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
247	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "fs_delete",
248	        toolName,
249	        targetResources: extractTargetResources(toolName, args),
250	        success: false,
251	        output: "",
252	        error: `${refusedDeletion}.`,
253	        durationMs: 0,
254	        candidateMutated: false,
255	        status: "DENIED",
256	        timestamp: new Date().toISOString(),
257	        simulated: Boolean(this.config.dryRun),
258	      },
259	      shouldExit: false,
260	    };
261	  }
262	
263	  this.ui.printToolCall(toolName, args);
264	  const dispatch = ++this.toolDispatchSeq;
265	  this.observer?.onToolStart?.({ dispatch, callId: call.id, tool: toolName, args });
266	  const subject = String(args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? "").replace(/\s+/g, " ").slice(0, 120);
267	  this.activity("tool", { tool: toolName, ...(subject ? { subject } : {}) });
268	
269	  const cap = this.capabilityRegistry.getByToolName(toolName);
270	  // Tools outside the registry (MCP servers, plugins) are treated as running code: review mode asks before them.
271	  const effect: EffectClass = cap ? cap.effect : READ_ONLY_TOOLS.has(toolName) ? "read_workspace" : "exec";
272	  const egressOrigin = effect === "egress" ? egressOriginOf(toolName, args) : undefined;
273	  const isTrusted = isWorkspaceTrusted(this.config.workspace, this.isReadOnly());
274	  const mode = this.getApprovalMode();
275	  if (this.checkpointReadOnlyFallback && ["egress", "delegate", "context_inject", "write_workspace"].includes(effect)) {
276	    const cancelMsg = `Read-only fallback: ${toolName} is disabled because the workspace could not be safely checkpointed.`;
277	    if (this.flightRecorder) {
278	      this.flightRecorder.recordToolResult(
279	        currentStep,
280	        call.id,
281	        toolName,
282	        false,
283	        cancelMsg,
284	        0,
285	        "CHECKPOINT_READ_ONLY_FALLBACK"
286	      );
287	    }
288	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg });
289	    return {
290	      receipt: {
291	        invocationId: call.id,
292	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
293	        actor,
294	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
295	        capabilityId: cap?.id || toolName,
296	        toolName,
297	        targetResources: extractTargetResources(toolName, args),
298	        success: false,
299	        output: "",
300	        error: cancelMsg,
301	        durationMs: 0,
302	        candidateMutated: false,
303	        status: "DENIED",
304	        denialReason: "CHECKPOINT_READ_ONLY_FALLBACK",
305	        timestamp: new Date().toISOString(),
306	        simulated: Boolean(this.config.dryRun),
307	      },
308	      shouldExit: false,
309	    };
310	  }
311	  // WP-GS-04: optional confirm on workspace skill activation (isUntrustedSource).
312	  let activateIsUntrustedSource = false;
313	  if (toolName === "activate_skill" && skillConfirmWorkspaceEnabled()) {
314	    const named = typeof args?.name === "string" ? this.skillManager.getSkill(args.name) : null;
315	    activateIsUntrustedSource = Boolean(named?.isWorkspaceSkill);
316	  }
317	  const verificationSecurity = this.bridge.getSecurityManager();
318	  // GV-1: the effective policy of this workspace. Its command prefixes and `approval.require_human` ask in every mode,
319	  // and the approval settings are clamped here whatever built this agent's configuration.
320	  const managed: EffectivePolicy = verificationSecurity.getEffectivePolicy();
321	  const managedCommand = toolName === "run_command" && typeof args.command === "string" ? decideManagedCommand(managed, splitSubcommands(args.command)) : undefined;
322	  const human: HumanRequirement | undefined = managedCommand?.decision === "prompt" ? { message: managedCommand.message, source: managedCommand.source } : humanRequirementForEffect(managed, effect);
323	  const askedContext: PolicyContext = {
324	    mode,
325	    trusted: isTrusted,
326	    sandbox: this.config.sandbox,
327	    approvedEgressOrigins: this.approvedEgressOrigins,
328	    egressOrigin,
329	    fullAccess: Boolean(this.config.fullAccess) && !this.isReadOnly(),
330	    isUntrustedSource: activateIsUntrustedSource,
331	  };
332	  const policyContext: PolicyContext = clampApprovalSettings(managed, askedContext, human);
333	  const policyDenial = (cancelMsg: string, denialReason: string) => {
334	    if (this.flightRecorder) this.flightRecorder.recordToolResult(currentStep, call.id, toolName, false, cancelMsg, 0, denialReason);
335	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg, denied: true });
336	    return {
337	      receipt: {
338	        invocationId: call.id,
339	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
340	        actor,
341	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
342	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
343	        toolName,
344	        targetResources: extractTargetResources(toolName, args),
345	        success: false,
346	        output: "",
347	        error: cancelMsg,
348	        durationMs: 0,
349	        candidateMutated: false,
350	        status: "DENIED",
351	        denialReason,
352	        timestamp: new Date().toISOString(),
353	        simulated: Boolean(this.config.dryRun),
354	      } as ExecutionReceipt,
355	      shouldExit: false,
356	    };
357	  };
358	  if (managedCommand?.decision === "forbidden") {
359	    return policyDenial(`Error: ${managedCommand.message} It is not run in any mode. Do the work another way, or report what you could not do.`, "MANAGED_POLICY_FORBIDDEN");
360	  }
361	  // A managed `egress.allowed_domains` decides the destination a call names. The project's own list keeps its existing
362	  // check in the fetch tool; here the merged list applies as the policy library matches it.
363	  if (effect === "egress" && typeof args.url === "string" && managed.egress.allowed_domains.tiers.some((tier) => tier.source.tier !== "project")) {
364	    let hostName = "";
365	    try {
366	      hostName = new URL(args.url).hostname;
367	    } catch {
368	      // A destination that cannot be read cannot be shown to be on the list.
369	    }
370	    if (!hostName) {
371	      return policyDenial(`Error: '${String(args.url).slice(0, 120)}' is not a URL whose host can be checked against the managed allowlist (egress.allowed_domains). ${describeSource(managed.egress.allowed_domains.source)}`, "MANAGED_POLICY_EGRESS");
372	    }
373	    const reachable = permitsEgressHost(managed, hostName);
374	    if (!reachable.allowed) return policyDenial(`Error: ${reachable.message}`, "MANAGED_POLICY_EGRESS");
375	  }
376	  // DV-3: a test edited through the shell is recorded against the obligation that names it (the CS-2 snapshot and diff).
377	  verificationSecurity.setShellChangeObserver(this.objective?.obligations?.length ? (changes: VerificationShellChange[], scan: { complete: boolean }) => {
378	    if (!this.objective) return;
379	    if (!scan.complete) {
380	      recordUnverifiableTestEdit(this.objective, "<workspace-scan>", "The bounded shell snapshot did not cover the entire workspace; verification-file edits may be missing.");
381	    }
382	    for (const c of changes) {
383	      if (c.class !== "test_file") continue;
384	      if (c.beforeText === undefined) {
385	        recordUnverifiableTestEdit(this.objective, c.path, "The changed test file exceeded the retained snapshot size, so weakening could not be assessed.");
386	        continue;
387	      }
388	      recordTestEdit(this.objective, { path: c.path, before: c.beforeText, after: c.afterText ?? "" });
389	    }
390	  } : undefined);
391	  const verificationAuthority: VerificationEditContext = { role: this.role, fullAccess: policyContext.fullAccess, operator: Boolean(onConfirm) };
392	  let verificationEdit = verificationSecurity.verificationEditDecision(toolName, args, verificationAuthority);
393	  let verificationQuestion: NeedsInputQuestion | undefined;
394	  if (verificationEdit?.action === "deny" && verificationEdit.needsDecision) {
395	    // VC-9: nobody to ask. An answer from a previous blocked run settles it; otherwise the turn ends BLOCKED with the question.
396	    verificationQuestion = buildNeedsInput(
397	      "verification_edit",
398	      `Allow ${toolName} to change ${verificationEdit.path} (${verificationEdit.class}, rule '${verificationEdit.rule}')?`,
399	      { tool: toolName, path: verificationEdit.path, class: verificationEdit.class },
400	      toolName,
401	      verificationEdit.path,
402	      verificationEdit.class,
403	    );
404	    if (this.headlessDecision(verificationQuestion) === "approve") {
405	      verificationAuthority.approved = { path: verificationEdit.path };
406	      verificationEdit = verificationSecurity.verificationEditDecision(toolName, args, verificationAuthority);
407	      verificationQuestion = undefined;
408	    }
409	  }
410	  if (verificationEdit?.action === "deny") {
411	    const declined = verificationQuestion && this.operatorAnswers.get(verificationQuestion.id) === "decline";
412	    const cancelMsg = verificationSecurity.refuseVerificationEdit(verificationEdit, toolName, this.role).error
413	      + (verificationQuestion ? (declined ? " The operator declined this edit." : ` needs_input ${verificationQuestion.id}: the run ends BLOCKED so the operator can decide.`) : "");
414	    this.syncVerificationAttempts();
415	    if (this.flightRecorder) {
416	      this.flightRecorder.recordToolResult(currentStep, call.id, toolName, false, cancelMsg, 0, VERIFICATION_CONFIG_PROTECTED);
417	    }
418	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg });
419	    return {
420	      receipt: {
421	        invocationId: call.id,
422	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
423	        actor,
424	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
425	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
426	        toolName,
427	        targetResources: extractTargetResources(toolName, args),
428	        success: false,
429	        output: "",
430	        error: cancelMsg,
431	        durationMs: 0,
432	        candidateMutated: false,
433	        status: "DENIED",
434	        denialReason: VERIFICATION_CONFIG_PROTECTED,
435	        timestamp: new Date().toISOString(),
436	        simulated: Boolean(this.config.dryRun),
437	      },
438	      shouldExit: false,
439	    };
440	  }
441	  // CS-9: the operator's command rules. `forbidden` refuses in every mode; `prompt` asks unless --yes; `allow` removes the
442	  // normal prompt only (every other control below still applies). The deciding rule is recorded for the session export.
443	  if (this.commandRulesNotice) {
444	    // The file is refused whole (unchanged); the notice says what that costs, so a dropped `forbidden` is not a surprise.
445	    const notice = `[nexus] command_rules: ${this.commandRulesNotice} Its forbidden and prompt rules are NOT enforced until the file is fixed.`;
446	    this.commandRulesNotice = undefined;
447	    if (this.depth === 0) {
448	      if (this.observer?.onNotice) this.observer.onNotice(notice);
449	      else console.warn(notice);
450	    }
451	  }
452	  const operatorVerdict: CommandVerdict | null = toolName === "run_command" && typeof args.command === "string" ? decideCommand(this.commandRules, args.command) : null;
453	  // GV-1 `commands.disable_allow_rules`: the operator's `allow` rules are not used; `prompt` and `forbidden` keep working.
454	  const ruleVerdict = operatorVerdict?.decision === "allow" && managed.commands.disable_allow_rules.value ? null : operatorVerdict;
455	  const recordRule = (verdict: CommandVerdict, effectText: CommandRuleDecision["effect"]): void => {
456	    this.commandRuleDecisions.push({
457	      timestamp: new Date().toISOString(),
458	      tool: toolName,
459	      command: redactSecrets(String(args.command)).replace(/\s+/g, " ").slice(0, 200),
460	      decision: verdict.decision,
461	      effect: effectText,
462	      rule: verdict.rule.index,
463	      rules: verdict.rules.map((r) => r.index),
464	      prefix: describePrefix(verdict.rule),
465	      ...(verdict.rule.justification ? { justification: verdict.rule.justification } : {}),
466	    });
467	    if (this.commandRuleDecisions.length > 500) this.commandRuleDecisions.splice(0, this.commandRuleDecisions.length - 500);
468	    this.syncVerificationAttempts();
469	  };
470	  if (ruleVerdict?.decision === "forbidden") {
471	    recordRule(ruleVerdict, "refused");
472	    const cancelMsg = `Error: this command is refused by the operator's command rule ${ruleVerdict.rule.index} (forbidden: ${describePrefix(ruleVerdict.rule)})${ruleVerdict.rule.justification ? `: ${ruleVerdict.rule.justification}` : ""}. It is not run in any mode. Do the work another way, or report what you could not do.`;
473	    if (this.flightRecorder) this.flightRecorder.recordToolResult(currentStep, call.id, toolName, false, cancelMsg, 0, "COMMAND_RULE_FORBIDDEN");
474	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg, denied: true });
475	    return {
476	      receipt: {
477	        invocationId: call.id,
478	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
479	        actor,
