518	        invocationId: call.id,
519	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
520	        actor,
521	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
522	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "activate_skill",
