552	      JSON.stringify(args),
553	    );
554	    preApproved = this.headlessDecision(toolQuestion) === "approve";
555	    if (preApproved && egressOrigin) this.approvedEgressOrigins.add(egressOrigin);
556	  }
557	
558	  if (askOperator && !preApproved) {
559	    if (!onConfirm) {
560	      const declined = toolQuestion && this.operatorAnswers.get(toolQuestion.id) === "decline";
