562	      const decidedBy = approvalDecisionSource(managed, askedContext);
563	      const operatorRule = ruleAsks && !policyAsk ? ruleVerdict!.rule.index : undefined;
564	      const approvalGuidance = human
565	        ? human.message
566	        : decidedBy.tier !== "default"
567	          ? `Managed policy disables automatic approvals here. ${describeSource(decidedBy)}`
568	          : `${effect === "egress"
569	            ? "Run with --yes to explicitly allow egress without an operator prompt."
570	            : "Run with --yes or --mode auto to explicitly select automatic approvals."} ${describeSource(operatorRule === undefined ? decidedBy : { tier: "operator-rules", ...(this.commandRules.file ? { file: this.commandRules.file } : {}), key: `rules[${operatorRule}]` })}`;
571	      const cancelMsg = reissuesInterrupted
572	        ? `Error: this '${toolName}' call matches one interrupted with an unknown outcome and may already have taken effect. It is not repeated without an explicit operator decision; inspect its effects first.${toolQuestion ? (declined ? " The operator declined this action." : ` needs_input ${toolQuestion.id}: the run ends BLOCKED so the operator can decide.`) : ""}`
