574	      const receipt: ExecutionReceipt = {
575	        invocationId: call.id,
576	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
577	        actor,
578	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
579	        capabilityId:
580	          this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
581	        toolName,
582	        targetResources: extractTargetResources(toolName, args),
583	        success: false,
584	        output: "",
585	        error: cancelMsg,
586	        durationMs: 0,
587	        candidateMutated: false,
588	        status: "DENIED",
589	        denialReason: "DECISION_REQUIRED_NO_OPERATOR",
590	        timestamp: new Date().toISOString(),
591	        simulated: Boolean(this.config.dryRun),
592	      };
593	      if (this.flightRecorder) {
594	        this.flightRecorder.recordToolResult(
595	          currentStep,
596	          call.id,
597	          toolName,
598	          false,
599	          cancelMsg,
600	          0,
601	          "DECISION_REQUIRED_NO_OPERATOR"
602	        );
603	      }
604	      this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg });
605	      return { receipt, shouldExit: false };
606	    }
607	
608	    this.activity("approval", { tool: toolName, ...(subject ? { subject } : {}) });
609	    if (injectionAsk && this.suspectedInjection) console.log(`⚠️ ${toolName} follows a result from ${this.suspectedInjection.tool} that looks like prompt injection (${this.suspectedInjection.signals.join(", ")}). Approve only what you asked for.`);
610	    if (verificationEdit?.action === "ask") console.log(`⚠️ ${toolName} changes verification configuration: ${verificationEdit.path} (${verificationEdit.class}).`);
611	    if (toolName === "run_command") {
612	      const networkNotice = sandboxNetworkNotice(String(args?.command ?? ""), Boolean(this.config.sandbox) && this.config.sandbox !== "none");
613	      if (networkNotice) console.log(`⚠️ ${networkNotice}`);
614	    }
615	    if (reissuesInterrupted) console.log(`⚠️ ${toolName} matches a call interrupted with unknown outcome; it may already have taken effect.`);
616	    if (human) console.log(`⚠️ ${human.message}`);
617	    // Where managed policy requires a human or disables automatic approval, a front end's own "approve everything"
618	    // state must not answer: the operator decides this call.
