622	      if (approved) verificationAuthority.approved = { path: verificationEdit.path };
623	      else {
624	        verificationSecurity.refuseVerificationEdit(verificationEdit, toolName, this.role);
625	        this.syncVerificationAttempts();
626	      }
627	    }
628	    if (approved && egressOrigin) this.approvedEgressOrigins.add(egressOrigin);
629	    if (approved) this.activity("tool", { tool: toolName, ...(subject ? { subject } : {}) });
630	    if (!approved) {
631	      this.turnDenials++;
632	      console.log(`⚠️ Tool execution cancelled by user.`);
633	      const cancelMsg = reissuesInterrupted
634	        ? "Error: The operator did not approve retrying this interrupted call. Its outcome remains unknown; inspect its effects before trying again."
635	        : "Error: Execution was rejected by the user. Ask the user for clarification or proceed with an alternative approach.";
636	      const receipt: ExecutionReceipt = {
637	        invocationId: call.id,
638	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
639	        actor,
640	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
641	        capabilityId:
642	          this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
643	        toolName,
644	        targetResources: extractTargetResources(toolName, args),
645	        success: false,
646	        output: "",
647	        error: cancelMsg,
648	        durationMs: 0,
649	        candidateMutated: false,
650	        status: "DENIED",
651	        timestamp: new Date().toISOString(),
652	        simulated: Boolean(this.config.dryRun),
653	      };
654	      if (this.flightRecorder) {
655	        this.flightRecorder.recordToolResult(
656	          currentStep,
657	          call.id,
658	          toolName,
659	          false,
660	          cancelMsg,
661	          0,
662	          "Rejected by user"
663	        );
664	      }
665	      this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg, denied: true });
