667	    }
668	  }
669	  this.ui.startSpinner(`Executing ${toolName}...`);
670	  await this.pluginManager.notifyToolCall(toolName, args);
671	
672	  const context: InvocationContext = {
673	    workspaceRoot: this.config.workspace,
674	    dryRun: this.config.dryRun,
675	    readOnly: this.isReadOnly(),
676	    bridge: this.bridge,
677	    metadata: { actor, stepIndex: currentStep, verificationAuthority, sandbox: this.config.sandbox },
678	    defaultHandler: async (tName, tArgs) => {
679	      if (this.mcpManager.isMcpTool(tName)) {
680	        return await this.mcpManager.executeMcpTool(tName, tArgs);
681	      }
682	      if (this.pluginManager.isCustomTool(tName)) {
683	        return await this.pluginManager.executeCustomTool(tName, tArgs);
684	      }
685	      return await this.pluginManager.executeToolPipeline(
686	        tName,
687	        tArgs,
688	        async (pipeArgs: any) => this.bridge.executeTool(tName, pipeArgs, verificationAuthority)
689	      );
690	    },
691	  };
692	
693	  const effectiveTaskId = this.activeWorktree?.taskId || this.currentTaskId;
694	  // Worktree task IDs scope tool authority and execution receipts, but durable state is
695	  // intentionally keyed by the parent session ID (see checkpointDurableState). Keep the
696	  // operation journal on that durable identity so recordOperationStart/End can find the
697	  // state initialized before a speculative worktree is created.
698	  const durableTaskId = this.currentTaskId;
699	  if (typeof (this.client as any)?.setTaskId === "function") this.client.setTaskId(effectiveTaskId);
700	  if (typeof (this.plannerClient as any)?.setTaskId === "function") this.plannerClient.setTaskId(effectiveTaskId);
701	  if (typeof (this.coderClient as any)?.setTaskId === "function") this.coderClient.setTaskId(effectiveTaskId);
