737	  }
738	  // A tool of a group not offered yet still runs (the model may know it from earlier); offer its group from now on.
739	  const calledGroup = toolGroupOf(toolName);
740	  if (calledGroup) this.enabledToolGroups.add(calledGroup);
741	  const workspaceAvailableBeforeBytes = toolName === "run_command" && process.env.NEXUS_EVAL_TOOL_RECEIPTS === "1"
742	    ? this.workspaceAvailableBytes()
743	    : null;
744	  let receipt: ExecutionReceipt;
745	  try {
746	    // activate_skill stamps attribution inside the handler; other tools inherit the current activation.
747	    const priorAttr = toolName === "activate_skill" ? {} : skillAttr();
