749	      {
750	        invocationId: call.id,
751	        taskId: effectiveTaskId,
752	        actor,
753	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
754	        toolName,
755	        args,
756	        stepIndex: currentStep,
757	        skillAttribution: priorAttr,
