796	    } catch (err: any) {
797	      this.reportPersistenceFailure("operation_end", err);
798	    }
799	  }
800	
801	  await this.pluginManager.notifyToolResult(toolName, {
802	    success: receipt.success,
803	    output: receipt.output,
804	    error: receipt.error,
805	  });
