807	  if (toolName === "run_tests" && this.objective && this.durable) {
808	    try {
809	      const parsed = JSON.parse(receipt.output || "{}");
810	      const state = this.verifierState();
811	      if (state && typeof parsed.command === "string" && parsed.command !== "none" && !parsed.noVerifier) {
