841	        if (this.objective && !this.turnConvergence) {
842	          const signal = convergenceSignal(this.objective, this.config.continuation?.verifierConvergenceAttempts, parsed.command);
843	          if (signal.state !== "converging") {
844	            this.turnConvergenceUpTo = this.objective.verification.at(-1)?.n;
845	            this.turnConvergence = { state: signal.state, evidence: signal.evidence, attempts: convergenceHistory(signal.attempts) };
846	          }
847	        }
848	      }
849	    } catch {}
850	  }
851	  // Track file modifications
852	  if (receipt.success && ["write_file", "edit_file", "patch_file", "delete_file"].includes(toolName)) {
853	    const p = args.path || args.target_file || args.file_path;
854	    if (typeof p === "string" && p.trim()) {
855	      this.modifiedFiles.add(path.resolve(this.config.workspace, p.trim()));
856	    }
857	  }
858	  // Only a successful operation that actually changed its file is reported as a change.
859	  if (diffTarget && before && receipt.success) {
860	    try {
861	      const display = path.relative(this.config.workspace, diffTarget) || path.basename(diffTarget);
862	      const change = describeChange(display, before, snapshot(diffTarget));
863	      if (change) {
864	        this.modifiedFiles.add(diffTarget);
865	        if (this.objective?.obligations?.length) {
866	          const after = snapshot(diffTarget);
867	          recordTestEdit(this.objective, { path: display, before: before.state === "text" ? before.content : "", after: after.state === "text" ? after.content : "" });
868	        }
869	        this.observer?.onFileChange?.({ dispatch, callId: call.id, tool: toolName, path: display, change });
870	      }
871	    } catch {}
872	  }
873	  // VR-3: a sandbox refusal is a typed receipt and flight record. Only structured denials from confinement code paths
874	  // become events; text matching on arbitrary errors would mislabel ordinary failures as sandbox denials.
875	  const sandboxEvent = receipt.sandboxEvents?.[0];
876	  if (sandboxEvent) this.recordSandboxDenialEvent?.(sandboxEvent);
877	
878	  this.ui.stopSpinner(receipt.success);
879	
880	  logAudit({
881	    workspace: this.config.workspace,
882	    tool: toolName,
883	    args,
884	    success: receipt.success,
885	    durationMs: receipt.durationMs,
886	    error: receipt.error,
887	  });
888	
889	  if (this.flightRecorder) {
890	    this.flightRecorder.recordToolResult(
891	      currentStep,
892	      call.id,
893	      toolName,
894	      receipt.success,
895	      receipt.output,
896	      receipt.durationMs,
897	      receipt.error
898	    );
899	    if (sandboxEvent) this.flightRecorder.recordSandboxDenial(currentStep, sandboxEvent);
900	    if (toolName === "update_plan" && receipt.success) {
901	      this.flightRecorder.recordDurableState(currentStep, {
902	        plan: this.activePlan,
903	      });
904	    }
905	    if (
906	      receipt.success &&
907	      ["write_file", "edit_file", "patch_file"].includes(toolName)
908	    ) {
909	      this.flightRecorder.recordFileDiff(
910	        currentStep,
911	        args.path || args.target_file || args.file_path || "unknown",
912	        receipt.output,
913	        args.replacements
914	      );
915	    }
916	    if (toolName === "task_completed" && receipt.success) {
917	      this.flightRecorder.recordSessionEnd(
918	        args.summary || "Task completed.",
919	        true,
920	        this.totalTokens
921	      );
922	    }
923	  }
924	
925	  this.ui.printToolResult(
926	    toolName,
927	    receipt.success,
928	    receipt.output,
929	    receipt.error
930	  );
931	  this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: receipt.success, output: receipt.output, error: receipt.error });
932	  if (receipt.success) this.turnRemovedObservations.delete(observationKey(toolName, call.function.arguments));
933	
934	  const shouldExit = toolName === "task_completed" && receipt.success;
935	  return { receipt, shouldExit };
936	}
