28	import { buildNeedsInput, type NeedsInputQuestion } from "./needs_input.js";
29	import {
30	  skillConstraintsEnabled,
31	  skillConfirmWorkspaceEnabled,
32	  resolveSkillToolAllowed,
33	  skillIntegrityMode,
34	} from "./skill_activation.js";
35	import * as fs from "node:fs";
36	
37	export async function dispatchToolCallImpl(this: any, call: ToolCall,
38	    currentStep: number,
39	    actor: "agent" | "subagent" = "agent",
40	    onConfirm?: ConfirmHandler): Promise<{ receipt: ExecutionReceipt; shouldExit: boolean }> {
41	  const toolName = call.function.name;
42	  let args: any = {};
43	  let structurallyRepaired = (call as any).repaired === "structural";
44	
45	  try {
46	    args =
47	      typeof call.function.arguments === "string"
48	        ? JSON.parse(call.function.arguments)
49	        : call.function.arguments;
50	  } catch {
51	    if (typeof call.function.arguments === "string") {
52	      try {
53	        const { value, repaired } = repairJsonWithClass(call.function.arguments);
54	        if (repaired === "structural") structurallyRepaired = true;
55	        args = value && typeof value === "object" ? value : { raw: call.function.arguments };
56	      } catch {
57	        structurallyRepaired = true;
58	        args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
59	      }
60	    } else {
61	      args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
62	    }
63	  }
64	  if (structurallyRepaired && isWriteOrExecTool(toolName)) {
65	    return {
66	      receipt: {
67	        invocationId: call.id,
68	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
69	        actor,
70	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
71	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
72	        toolName,
73	        targetResources: [],
74	        success: false,
75	        output: "",
76	        error: `Tool call "${toolName}" rejected: arguments required structural JSON repair (truncated or unclosed string/bracket). Re-issue the call with complete valid JSON arguments.`,
77	        durationMs: 0,
78	        candidateMutated: false,
79	        status: "DENIED",
80	        timestamp: new Date().toISOString(),
81	        simulated: Boolean(this.config.dryRun),
82	      },
83	      shouldExit: false,
84	    };
85	  }
86	
87	  args = normalizeToolArguments(toolName, args, this.getEffectiveTools());
88	
89	  const skillAttr = () => this.skillActivations?.attribution?.() ?? {};
90	  const recordReceipt = (receipt: ExecutionReceipt) => {
91	    this.lastToolReceipts = [...(this.lastToolReceipts || []), receipt].slice(-32);
92	    return receipt;
93	  };
94	
95	  // Delegated authority is checked at the dispatcher as well as when schemas are built. This is the
96	  // enforcement point for malformed/native/text tool calls and extension tools alike.
97	  if (this.delegatedToolAllowList && !this.delegatedToolAllowList.has(toolName)) {
98	    return {
99	      receipt: recordReceipt({
100	        invocationId: call.id,
101	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
102	        actor,
103	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
104	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
105	        toolName,
106	        targetResources: extractTargetResources(toolName, args),
107	        success: false,
108	        output: "",
109	        error: `Delegation authority denied tool '${toolName}'.`,
110	        durationMs: 0,
111	        candidateMutated: false,
112	        status: "DENIED",
113	        denialReason: "DELEGATION_AUTHORITY",
114	        timestamp: new Date().toISOString(),
115	        simulated: Boolean(this.config.dryRun),
116	        ...skillAttr(),
117	      }),
118	      shouldExit: false,
119	    };
120	  }
121	
122	  // A restricted role is refused any tool outside its allow-list, whatever the model was told or claims. A write or
123	  // exec call in read-only mode is left to the read-only check, which refuses it with its own reason.
124	  const roleAllowed = roleToolAllowList(this.role);
125	  const roleDenied = roleToolDenyList(this.role);
126	  const denyListed = Boolean(roleDenied?.has(toolName));
127	  if (denyListed || (roleAllowed && !roleAllowed.has(toolName) && !(this.isReadOnly() && isWriteOrExecTool(toolName)))) {
128	    return {
129	      receipt: recordReceipt({
130	        invocationId: call.id,
131	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
132	        actor,
133	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
134	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
135	        toolName,
136	        targetResources: [],
137	        success: false,
138	        output: "",
139	        error: denyListed
140	          ? `Tool "${toolName}" is not available to role '${this.role}': tools that reach outside the task (${[...roleDenied!].join(", ")}) are not part of that role. Do the work with the tools you have, or report what you could not do.`
141	          : `Tool "${toolName}" is not permitted for role '${this.role}'. Permitted tools: ${[...roleAllowed!].join(", ")}.`,
142	        durationMs: 0,
143	        candidateMutated: false,
144	        status: "DENIED",
