    };
  }

  public getRegistry(): CapabilityRegistry {
    return this.registry;
  }

  public getHooks(): Required<SpineHooks> {
    return { ...this.hooks };
  }

  public setHook<K extends keyof SpineHooks>(hookName: K, hook: SpineHooks[K]): void {
    if (hook) {
      this.hooks[hookName] = hook as any;
    }
